"""Keyed pseudo-random function with random access (AES-256 used as a PRP over 16-byte blocks).

``prf_u64(key, domain, idx)`` returns a uint64 per integer index, vectorised.
Random access matters: watermark sequences are addressed by timestamp / row key,
so a cropped, shuffled or subsampled copy still lines up with the key stream.
"""
from __future__ import annotations

import hashlib
import numpy as np
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes


def domain_id(label: str) -> int:
    """Stable 64-bit domain separator from a string label (e.g. a column name)."""
    return int.from_bytes(hashlib.blake2b(label.encode("utf-8"), digest_size=8).digest(), "little")


def prf_u64(key: bytes, domain: int, idx: np.ndarray) -> np.ndarray:
    if len(key) != 32:
        raise ValueError("PRF key must be 32 bytes")
    idx = np.ascontiguousarray(idx, dtype=np.int64)
    blk = np.empty((idx.size, 2), dtype="<u8")
    blk[:, 0] = idx.view(np.uint64)
    blk[:, 1] = np.uint64(domain)
    enc = Cipher(algorithms.AES(key), modes.ECB()).encryptor()
    out = enc.update(blk.tobytes()) + enc.finalize()
    return np.frombuffer(out, dtype="<u8").reshape(-1, 2)[:, 0].astype(np.uint64)


def prf_sign(key: bytes, domain: int, idx: np.ndarray) -> np.ndarray:
    """Keyed +/-1 sequence (float64)."""
    return np.where(prf_u64(key, domain, idx) & np.uint64(1), 1.0, -1.0)


def prf_unit(key: bytes, domain: int, idx: np.ndarray) -> np.ndarray:
    """Keyed uniform [0,1) sequence (53 bits)."""
    return (prf_u64(key, domain, idx) >> np.uint64(11)).astype(np.float64) / float(1 << 53)
